Baik, saya bangun **Kebun Siege** sekarang — Tower Defense satu berkas dengan gaya Clean Modern & Soft Gradient, tiga penjaga, upgrade, dan Slow-Motion.

```html
<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=no">
<title>Kebun Siege</title>
<style>
  * { margin:0; padding:0; box-sizing:border-box; -webkit-tap-highlight-color:transparent; }
  html,body { width:100%; height:100%; overflow:hidden; background:#1b2a24; font-family:'Segoe UI',system-ui,sans-serif; }
  #wrap { position:absolute; inset:0; display:flex; align-items:center; justify-content:center; }
  canvas { display:block; border-radius:14px; box-shadow:0 18px 60px rgba(0,0,0,.55); touch-action:none; }
  #muteBtn { position:absolute; top:14px; right:14px; z-index:20; width:44px; height:44px; border:none; border-radius:12px;
    background:rgba(255,255,255,.82); color:#2b4a3c; font-size:20px; cursor:pointer; box-shadow:0 4px 14px rgba(0,0,0,.2); }
  #muteBtn:active { transform:scale(.94); }
</style>
</head>
<body>
<div id="wrap"><canvas id="cv"></canvas></div>
<button id="muteBtn">🔊</button>
<script>
"use strict";
/* ============ SETUP ============ */
const cv = document.getElementById('cv'), ctx = cv.getContext('2d');
const W = 1280, H = 720;
function resize(){
  const s = Math.min(window.innerWidth/W, window.innerHeight/H);
  cv.width = W; cv.height = H;
  cv.style.width = (W*s)+'px'; cv.style.height = (H*s)+'px';
}
window.addEventListener('resize', resize); resize();

/* ============ AUDIO ============ */
let actx = null, muted = false;
function unlockAudio(){ if(!actx){ try{ actx = new (window.AudioContext||window.webkitAudioContext)(); }catch(e){} } if(actx && actx.state==='suspended') actx.resume(); }
function tone(freq, dur, type, vol, slideTo){
  if(!actx || muted) return;
  const o = actx.createOscillator(), g = actx.createGain();
  o.type = type||'sine'; o.frequency.setValueAtTime(freq, actx.currentTime);
  if(slideTo) o.frequency.exponentialRampToValueAtTime(slideTo, actx.currentTime+dur);
  g.gain.setValueAtTime(vol||0.12, actx.currentTime);
  g.gain.exponentialRampToValueAtTime(0.0001, actx.currentTime+dur);
  o.connect(g); g.connect(actx.destination); o.start(); o.stop(actx.currentTime+dur+0.02);
}
const SFX = {
  shoot: ()=>tone(680,0.07,'square',0.05,420),
  splash: ()=>tone(300,0.14,'sawtooth',0.06,140),
  coin: ()=>{tone(880,0.08,'sine',0.09); setTimeout(()=>tone(1320,0.1,'sine',0.08),70);},
  kill: ()=>tone(220,0.16,'triangle',0.07,90),
  place: ()=>tone(520,0.1,'sine',0.1,760),
  upgrade: ()=>{tone(600,0.09,'sine',0.1); setTimeout(()=>tone(900,0.12,'sine',0.1),80);},
  wave: ()=>{tone(440,0.12,'triangle',0.1); setTimeout(()=>tone(660,0.16,'triangle',0.1),120);},
  slow: ()=>tone(900,0.5,'sine',0.09,300),
  leak: ()=>tone(160,0.3,'sawtooth',0.12,70),
  over: ()=>{tone(400,0.3,'triangle',0.12,200); setTimeout(()=>tone(200,0.5,'triangle',0.12,80),250);}
};
document.getElementById('muteBtn').addEventListener('click', e=>{
  e.stopPropagation(); unlockAudio(); muted = !muted;
  e.currentTarget.textContent = muted ? '🔇' : '🔊';
});
window.addEventListener('pointerdown', unlockAudio, {once:false});

/* ============ PATH ============ */
const PATH = [
  {x:-40,y:200},{x:200,y:200},{x:200,y:420},{x:470,y:420},{x:470,y:180},
  {x:760,y:180},{x:760,y:500},{x:1000,y:500},{x:1000,y:300},{x:1180,y:300}
];
const PATH_W = 62;
function pathLen(){
  let L=0; for(let i=1;i<PATH.length;i++) L+=Math.hypot(PATH[i].x-PATH[i-1].x, PATH[i].y-PATH[i-1].y);
  return L;
}
const TOTAL_LEN = pathLen();
function posAt(dist){
  let d = Math.max(0, Math.min(dist, TOTAL_LEN));
  for(let i=1;i<PATH.length;i++){
    const a=PATH[i-1], b=PATH[i], seg=Math.hypot(b.x-a.x,b.y-a.y);
    if(d<=seg){ const t=seg?d/seg:0; return {x:a.x+(b.x-a.x)*t, y:a.y+(b.y-a.y)*t}; }
    d-=seg;
  }
  const e=PATH[PATH.length-1]; return {x:e.x,y:e.y};
}
function distToPath(px,py){
  let best=1e9;
  for(let i=1;i<PATH.length;i++){
    const a=PATH[i-1], b=PATH[i];
    const dx=b.x-a.x, dy=b.y-a.y, L2=dx*dx+dy*dy;
    let t = L2? ((px-a.x)*dx+(py-a.y)*dy)/L2 : 0; t=Math.max(0,Math.min(1,t));
    const cx=a.x+dx*t, cy=a.y+dy*t;
    best = Math.min(best, Math.hypot(px-cx,py-cy));
  }
  return best;
}

/* ============ TOWER TYPES ============ */
const TOWERS = {
  semprot: { name:'Penjaga Semprot', cost:60, color:'#4FA3E3', accent:'#2F7FC1', range:150, dmg:9, rate:0.55, kind:'single', desc:'Tembakan cepat' },
  jaring:  { name:'Penjaga Jaring',  cost:90, color:'#7BC96F', accent:'#4E9E45', range:130, dmg:4, rate:0.9,  kind:'slow',   desc:'Perlambat area' },
  api:     { name:'Penjaga Api',     cost:140,color:'#F08A4B', accent:'#C9612A', range:165, dmg:16,rate:1.25, kind:'area',   desc:'Ledakan area' }
};
const UPGRADE_COST = [0, 70, 120];

/* ============ ENEMY TYPES ============ */
const ENEMIES = {
  ulat:   { name:'Ulat',   hp:34,  speed:52,  reward:12, color:'#8FD46A', r:15 },
  kumbang:{ name:'Kumbang',hp:70,  speed:40,  reward:18, color:'#6B5B95', r:17 },
  siput:  { name:'Siput',  hp:130, speed:26,  reward:26, color:'#E8B36B', r:19 },
  bos:    { name:'Raja Hama', hp:520, speed:22, reward:120, color:'#D95757', r:26 }
};

/* ============ GAME STATE ============ */
let G;
function newGame(){
  G = {
    state:'menu', time:0, coins:180, score:0, lives:10, wave:0,
    towers:[], enemies:[], bullets:[], particles:[], floaters:[],
    spawnQueue:[], spawnTimer:0, waveTimer:0, betweenWaves:3,
    selected:null, hoverCell:null, slowTimer:0, slowCd:0,
    shake:0, msg:'', msgTimer:0, totalKills:0
  };
}
newGame();

/* ============ WAVE GENERATION ============ */
function buildWave(n){
  const q=[]; const base = 5 + n*2;
  for(let i=0;i<base;i++){
    let t='ulat';
    if(n>=2 && i%4===3) t='kumbang';
    if(n>=4 && i%6===5) t='siput';
    q.push(t);
  }
  if(n%5===0 && n>0) q.push('bos');
  return q;
}
function startWave(){
  G.wave++;
  G.spawnQueue = buildWave(G.wave);
  G.spawnTimer = 0;
  G.msg = 'Gelombang '+G.wave+'!'; G.msgTimer = 2.2;
  SFX.wave();
}

/* ============ SPAWN ============ */
function spawnEnemy(type){
  const d = ENEMIES[type];
  const scale = 1 + (G.wave-1)*0.16;
  G.enemies.push({
    type, hp:d.hp*scale, maxHp:d.hp*scale, speed:d.speed, reward:d.reward,
    color:d.color, r:d.r, dist:0, slow:0, x:PATH[0].x, y:PATH[0].y, hitFlash:0
  });
}

/* ============ PLACEMENT ============ */
function canPlace(x,y){
  if(distToPath(x,y) < PATH_W/2 + 26) return false;
  if(x<40||x>W-40||y<60||y>H-40) return false;
  for(const t of G.towers) if(Math.hypot(t.x-x,t.y-y) < 62) return false;
  return true;
}
function placeTower(type,x,y){
  const d = TOWERS[type];
  if(G.coins < d.cost){ G.msg='Koin tidak cukup!'; G.msgTimer=1.4; return; }
  if(!canPlace(x,y)){ G.msg='Tidak bisa menanam di sini'; G.msgTimer=1.4; return; }
  G.coins -= d.cost;
  G.towers.push({ type, x, y, level:1, cd:0, angle:-Math.PI/2 });
  SFX.place();
  for(let i=0;i<10;i++) G.particles.push({x,y,vx:(Math.random()-.5)*120,vy:(Math.random()-.5)*120,life:.5,max:.5,color:d.color,r:3});
}
function upgradeTower(t){
  if(t.level>=3){ G.msg='Sudah level maksimal'; G.msgTimer=1.2; return; }
  const c = UPGRADE_COST[t.level];
  if(G.coins < c){ G.msg='Koin tidak cukup!'; G.msgTimer=1.4; return; }
  G.coins -= c; t.level++;
  SFX.upgrade();
  for(let i=0;i<12;i++) G.particles.push({x:t.x,y:t.y,vx:(Math.random()-.5)*140,vy:(Math.random()-.5)*140,life:.6,max:.6,color:'#FFD97D',r:3});
}

/* ============ COMBAT ============ */
function towerStats(t){
  const d = TOWERS[t.type], m = 1 + (t.level-1)*0.55;
  return { range: d.range*(1+(t.level-1)*0.12), dmg: d.dmg*m, rate: d.rate/(1+(t.level-1)*0.18), kind:d.kind };
}
function fire(t){
  const s = towerStats(t);
  let target=null, bestD=-1;
  for(const e of G.enemies){
    const dd = Math.hypot(e.x-t.x, e.y-t.y);
    if(dd <= s.range && e.dist > bestD){ bestD=e.dist; target=e; }
  }
  if(!target) return;
  t.angle = Math.atan2(target.y-t.y, target.x-t.x);
  G.bullets.push({ x:t.x, y:t.y, tx:target.x, ty:target.y, target, dmg:s.dmg, kind:s.kind, color:TOWERS[t.type].color, life:1.2, speed:520 });
  if(t.type==='api') SFX.splash(); else SFX.shoot();
}
function damageEnemy(e, dmg, kind){
  e.hp -= dmg; e.hitFlash = 0.15;
  if(kind==='slow') e.slow = Math.max(e.slow, 1.6);
  if(e.hp<=0){
    const idx = G.enemies.indexOf(e);
    if(idx>=0){
      G.enemies.splice(idx,1);
      G.coins += e.reward; G.score += e.reward; G.totalKills++;
      SFX.kill(); SFX.coin();
      G.floaters.push({x:e.x,y:e.y,text:'+'+e.reward,life:1,max:1,color:'#FFD97D'});
      for(let i=0;i<12;i++) G.particles.push({x:e.x,y:e.y,vx:(Math.random()-.5)*180,vy:(Math.random()-.5)*180,life:.6,max:.6,color:e.color,r:3});
    }
  }
}

/* ============ UPDATE ============ */
function update(dt){
  if(G.state!=='play') return;
  G.time += dt;
  if(G.msgTimer>0) G.msgTimer -= dt;
  if(G.shake>0) G.shake = Math.max(0, G.shake-dt*30);
  if(G.slowCd>0) G.slowCd -= dt;
  if(G.slowTimer>0) G.slowTimer -= dt;

  // wave logic
  if(G.spawnQueue.length>0){
    G.spawnTimer -= dt;
    if(G.spawnTimer<=0){ spawnEnemy(G.spawnQueue.shift()); G.spawnTimer = 0.75; }
  } else if(G.enemies.length===0){
    G.betweenWaves -= dt;
    if(G.betweenWaves<=0){ G.betweenWaves = 4; startWave(); }
  }

  // enemies
  const slowFactor = G.slowTimer>0 ? 0.5 : 1;
  for(let i=G.enemies.length-1;i>=0;i--){
    const e = G.enemies[i];
    if(e.hitFlash>0) e.hitFlash -= dt;
    if(e.slow>0) e.slow -= dt;
    const sp = e.speed * (e.slow>0?0.45:1) * slowFactor;
    e.dist += sp*dt;
    const p = posAt(e.dist); e.x=p.x; e.y=p.y;
    if(e.dist >= TOTAL_LEN){
      G.enemies.splice(i,1);
      G.lives--; G.shake = 12; SFX.leak();
      G.floaters.push({x:e.x,y:e.y,text:'-1 ❤',life:1.2,max:1.2,color:'#E5484D'});
      if(G.lives<=0){ G.state='over'; SFX.over(); }
    }
  }

  // towers
  for(const t of G.towers){
    t.cd -= dt;
    if(t.cd<=0){ const s=towerStats(t); t.cd = s.rate; fire(t); }
  }

  // bullets
  for(let i=G.bullets.length-1;i>=0;i--){
    const b = G.bullets[i];
    b.life -= dt;
    if(b.target && G.enemies.includes(b.target)){ b.tx=b.target.x; b.ty=b.target.y; }
    const dx=b.tx-b.x, dy=b.ty-b.y, d=Math.hypot(dx,dy);
    if(d < 14 || b.life<=0){
      if(b.kind==='area'){
        for(const e of G.enemies){
          if(Math.hypot(e.x-b.tx,e.y-b.ty) < 70) damageEnemy(e, b.dmg, 'area');
        }
        for(let k=0;k<14;k++) G.particles.push({x:b.tx,y:b.ty,vx:(Math.random()-.5)*260,vy:(Math.random()-.5)*260,life:.5,max:.5,color:'#F08A4B',r:4});
      } else if(b.target && G.enemies.includes(b.target)){
        damageEnemy(b.target, b.dmg, b.kind);
      }
      G.bullets.splice(i,1); continue;
    }
    const sp = b.speed*dt;
    b.x += dx/d*sp; b.y += dy/d*sp;
  }

  // particles & floaters
  for(let i=G.particles.length-1;i>=0;i--){
    const p=G.particles[i]; p.life-=dt; p.x+=p.vx*dt; p.y+=p.vy*dt; p.vy+=180*dt;
    if(p.life<=0) G.particles.splice(i,1);
  }
  for(let i=G.floaters.length-1;i>=0;i--){
    const f=G.floaters[i]; f.life-=dt; f.y-=40*dt;
    if(f.life<=0) G.floaters.splice(i,1);
  }
}

/* ============ DRAW HELPERS ============ */
function roundRect(x,y,w,h,r){ ctx.beginPath(); ctx.moveTo(x+r,y); ctx.arcTo(x+w,y,x+w,y+h,r); ctx.arcTo(x+w,y+h,x,y+h,r); ctx.arcTo(x,y+h,x,y,r); ctx.arcTo(x,y,x+w,y,r); ctx.closePath(); }
function lerp(a,b,t){ return a+(b-a)*t; }

/* ============ DRAW ============ */
function drawBackground(){
  const g = ctx.createLinearGradient(0,0,0,H);
  g.addColorStop(0,'#D6F0E0'); g.addColorStop(0.55,'#EAF7EE'); g.addColorStop(1,'#F6F1E4');
  ctx.fillStyle = g; ctx.fillRect(0,0,W,H);
  // soft hills
  ctx.fillStyle = 'rgba(180,220,190,0.35)';
  ctx.beginPath(); ctx.ellipse(240, 640, 420, 150, 0, 0, Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(980, 660, 480, 170, 0, 0, Math.PI*2); ctx.fill();
  // decorative bushes
  for(let i=0;i<14;i++){
    const x = (i*97+40)%W, y = 90 + ((i*53)%60);
    ctx.fillStyle = 'rgba(140,200,160,0.28)';
    ctx.beginPath(); ctx.arc(x,y,26,0,Math.PI*2); ctx.fill();
  }
}
function drawPath(){
  ctx.lineCap='round'; ctx.lineJoin='round';
  ctx.strokeStyle = 'rgba(120,160,130,0.35)'; ctx.lineWidth = PATH_W+16;
  ctx.beginPath(); ctx.moveTo(PATH[0].x,PATH[0].y);
  for(let i=1;i<PATH.length;i++) ctx.lineTo(PATH[i].x,PATH[i].y); ctx.stroke();
  const g = ctx.createLinearGradient(0,0,W,H);
  g.addColorStop(0,'#E8DCC0'); g.addColorStop(1,'#D9C9A6');
  ctx.strokeStyle = g; ctx.lineWidth = PATH_W;
  ctx.beginPath(); ctx.moveTo(PATH[0].x,PATH[0].y);
  for(let i=1;i<PATH.length;i++) ctx.lineTo(PATH[i].x,PATH[i].y); ctx.stroke();
  // dashes
  ctx.setLineDash([14,18]); ctx.strokeStyle='rgba(255,255,255,0.5)'; ctx.lineWidth=4;
  ctx.beginPath(); ctx.moveTo(PATH[0].x,PATH[0].y);
  for(let i=1;i<PATH.length;i++) ctx.lineTo(PATH[i].x,PATH[i].y); ctx.stroke();
  ctx.setLineDash([]);
}
function drawGoal(){
  const e = PATH[PATH.length-1];
  ctx.save(); ctx.translate(e.x, e.y);
  ctx.shadowColor='rgba(80,160,100,0.6)'; ctx.shadowBlur=22;
  ctx.fillStyle='#7BC96F'; ctx.beginPath(); ctx.arc(0,0,34,0,Math.PI*2); ctx.fill();
  ctx.shadowBlur=0;
  ctx.fillStyle='#4E9E45'; ctx.beginPath(); ctx.arc(0,-6,20,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='#8FD46A'; ctx.beginPath(); ctx.arc(-8,-12,10,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(9,-10,9,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='#fff'; ctx.font='bold 13px Segoe UI'; ctx.textAlign='center';
  ctx.fillText('INTI', 0, 26);
  ctx.restore();
}
function drawTower(t){
  const d = TOWERS[t.type];
  ctx.save(); ctx.translate(t.x,t.y);
  // base shadow
  ctx.fillStyle='rgba(60,90,70,0.18)'; ctx.beginPath(); ctx.ellipse(0,10,26,12,0,0,Math.PI*2); ctx.fill();
  // base
  const bg = ctx.createLinearGradient(0,-26,0,20);
  bg.addColorStop(0, d.color); bg.addColorStop(1, d.accent);
  ctx.fillStyle = bg; roundRect(-22,-22,44,44,14); ctx.fill();
  ctx.strokeStyle='rgba(255,255,255,0.55)'; ctx.lineWidth=2; roundRect(-22,-22,44,44,14); ctx.stroke();
  // barrel
  ctx.save(); ctx.rotate(t.angle);
  ctx.fillStyle = d.accent; roundRect(4,-7,26,14,7); ctx.fill();
  ctx.fillStyle='rgba(255,255,255,0.5)'; roundRect(20,-4,8,8,4); ctx.fill();
  ctx.restore();
  // eye
  ctx.fillStyle='#fff'; ctx.beginPath(); ctx.arc(-4,-4,7,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='#2b4a3c'; ctx.beginPath(); ctx.arc(-3,-4,3.4,0,Math.PI*2); ctx.fill();
  // level pips
  for(let i=0;i<t.level;i++){
    ctx.fillStyle='#FFD97D'; ctx.beginPath(); ctx.arc(-14+i*10, 16, 3.4, 0, Math.PI*2); ctx.fill();
  }
  ctx.restore();
}
function drawEnemy(e){
  ctx.save(); ctx.translate(e.x,e.y);
  ctx.fillStyle='rgba(60,90,70,0.18)'; ctx.beginPath(); ctx.ellipse(0,e.r*0.8,e.r*0.9,e.r*0.4,0,0,Math.PI*2); ctx.fill();
  const g = ctx.createRadialGradient(-e.r*0.3,-e.r*0.3,2,0,0,e.r*1.2);
  g.addColorStop(0, e.hitFlash>0?'#ffffff':e.color);
  g.addColorStop(1, e.hitFlash>0?'#ffdddd':e.color);
  ctx.fillStyle=g; ctx.beginPath(); ctx.arc(0,0,e.r,0,Math.PI*2); ctx.fill();
  ctx.strokeStyle='rgba(255,255,255,0.6)'; ctx.lineWidth=2; ctx.stroke();
  // eyes
  ctx.fillStyle='#fff'; ctx.beginPath(); ctx.arc(-e.r*0.32,-e.r*0.2,e.r*0.3,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(e.r*0.32,-e.r*0.2,e.r*0.3,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='#2b4a3c'; ctx.beginPath(); ctx.arc(-e.r*0.28,-e.r*0.2,e.r*0.15,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(e.r*0.36,-e.r*0.2,e.r*0.15,0,Math.PI*2); ctx.fill();
  // hp bar
  const w=e.r*2.2, hp=e.hp/e.maxHp;
  ctx.fillStyle='rgba(0,0,0,0.18)'; roundRect(-w/2,-e.r-14,w,6,3); ctx.fill();
  ctx.fillStyle = hp>0.5?'#7BC96F':hp>0.25?'#F0C24B':'#E5484D';
  roundRect(-w/2,-e.r-14,w*hp,6,3); ctx.fill();
  if(e.slow>0){ ctx.strokeStyle='rgba(120,200,255,0.85)'; ctx.lineWidth=2.5; ctx.beginPath(); ctx.arc(0,0,e.r+5,0,Math.PI*2); ctx.stroke(); }
  ctx.restore();
}
function drawBullet(b){
  ctx.save();
  ctx.shadowColor=b.color; ctx.shadowBlur=12; ctx.fillStyle=b.color;
  ctx.beginPath(); ctx.arc(b.x,b.y, b.kind==='area'?7:5, 0, Math.PI*2); ctx.fill();
  ctx.restore();
}
function drawParticles(){
  for(const p of G.particles){
    ctx.globalAlpha = Math.max(0,p.life/p.max);
    ctx.fillStyle=p.color; ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,Math.PI*2); ctx.fill();
  }
  ctx.globalAlpha=1;
  for(const f of G.floaters){
    ctx.globalAlpha = Math.max(0,f.life/f.max);
    ctx.fillStyle=f.color; ctx.font='bold 20px Segoe UI'; ctx.textAlign='center';
    ctx.fillText(f.text, f.x, f.y);
  }
  ctx.globalAlpha=1;
}
function drawHUD(){
  // top bar
  ctx.fillStyle='rgba(255,255,255,0.82)'; roundRect(16,14,W-32,58,16); ctx.fill();
  ctx.fillStyle='#2b4a3c'; ctx.font='bold 22px Segoe UI'; ctx.textAlign='left';
  ctx.fillText('🌻 Kebun Siege', 34, 52);
  ctx.font='bold 20px Segoe UI'; ctx.fillStyle='#C98A1E';
  ctx.fillText('🪙 '+G.coins, 300, 52);
  ctx.fillStyle='#D95757'; ctx.fillText('❤ '+G.lives, 440, 52);
  ctx.fillStyle='#4E9E45'; ctx.fillText('Gelombang '+G.wave, 560, 52);
  ctx.fillStyle='#2F7FC1'; ctx.fillText('Skor '+G.score, 780, 52);

  // tower buttons
  const types = ['semprot','jaring','api'];
  types.forEach((tp,i)=>{
    const d = TOWERS[tp], bx = 16+i*150, by = H-96;
    const sel = G.selected===tp;
    ctx.fillStyle = sel ? 'rgba(255,255,255,0.98)' : 'rgba(255,255,255,0.78)';
    roundRect(bx,by,138,80,14); ctx.fill();
    if(sel){ ctx.strokeStyle=d.color; ctx.lineWidth=3; roundRect(bx,by,138,80,14); ctx.stroke(); }
    ctx.fillStyle=d.color; roundRect(bx+10,by+10,32,32,9); ctx.fill();
    ctx.fillStyle='#2b4a3c'; ctx.font='bold 13px Segoe UI'; ctx.textAlign='left';
    ctx.fillText(d.name.replace('Penjaga ',''), bx+50, by+26);
    ctx.font='12px Segoe UI'; ctx.fillStyle='#5a7a68';
    ctx.fillText(d.desc, bx+50, by+44);
    ctx.fillStyle='#C98A1E'; ctx.font='bold 13px Segoe UI';
    ctx.fillText('🪙 '+d.cost, bx+14, by+68);
    ctx.fillStyle='#8aa89a'; ctx.font='11px Segoe UI';
    ctx.fillText('['+(i+1)+']', bx+112, by+68);
  });

  // slow-motion button
  const sx = W-190, sy = H-96;
  const ready = G.slowCd<=0;
  ctx.fillStyle = G.slowTimer>0 ? 'rgba(120,200,255,0.95)' : ready ? 'rgba(255,255,255,0.9)' : 'rgba(200,210,205,0.7)';
  roundRect(sx,sy,174,80,14); ctx.fill();
  ctx.fillStyle = ready?'#2F7FC1':'#8aa89a'; ctx.font='bold 15px Segoe UI'; ctx.textAlign='center';
  ctx.fillText('⏱ SLOW-MO', sx+87, sy+32);
  ctx.font='12px Segoe UI';
  ctx.fillText(G.slowTimer>0 ? 'Aktif '+G.slowTimer.toFixed(1)+'s' : ready ? 'Siap [Spasi]' : 'Cooldown '+Math.ceil(G.slowCd)+'s', sx+87, sy+56);

  // message
  if(G.msgTimer>0){
    ctx.globalAlpha = Math.min(1,G.msgTimer);
    ctx.fillStyle='rgba(43,74,60,0.9)'; ctx.font='bold 26px Segoe UI'; ctx.textAlign='center';
    ctx.fillText(G.msg, W/2, 120);
    ctx.globalAlpha=1;
  }
  // watermark
  ctx.fillStyle='rgba(255,255,255,0.35)'; ctx.font='12px Segoe UI'; ctx.textAlign='right';
  ctx.fillText('AISYS HTML5 Engine', W-24, H-16);
}
function drawPlacementHint(){
  if(!G.selected || !G.hoverCell) return;
  const {x,y} = G.hoverCell, d = TOWERS[G.selected];
  const ok = canPlace(x,y) && G.coins>=d.cost;
  ctx.save();
  ctx.globalAlpha=0.28; ctx.fillStyle = ok?'#7BC96F':'#E5484D';
  ctx.beginPath(); ctx.arc(x,y,d.range,0,Math.PI*2); ctx.fill();
  ctx.globalAlpha=0.9; ctx.strokeStyle = ok?'#4E9E45':'#E5484D'; ctx.lineWidth=2.5;
  ctx.setLineDash([8,8]); ctx.beginPath(); ctx.arc(x,y,d.range,0,Math.PI*2); ctx.stroke(); ctx.setLineDash([]);
  ctx.fillStyle = ok?'rgba(123,201,111,0.85)':'rgba(229,72,77,0.85)';
  roundRect(x-22,y-22,44,44,12); ctx.fill();
  ctx.restore();
}

/* ============ SCREENS ============ */
function drawMenu(){
  drawBackground();
  ctx.fillStyle='rgba(255,255,255,0.75)'; roundRect(W/2-320, H/2-200, 640, 400, 28); ctx.fill();
  ctx.textAlign='center';
  ctx.fillStyle='#2b4a3c'; ctx.font='bold 54px Segoe UI';
  ctx.fillText('🌻 Kebun Siege', W/2, H/2-100);
  ctx.font='20px Segoe UI'; ctx.fillStyle='#5a7a68';
  ctx.fillText('Tower Defense — lindungi kebun dari serangan hama!', W/2, H/2-52);
  ctx.font='16px Segoe UI'; ctx.fillStyle='#7a9a88';
  ctx.fillText('Tanam penjaga, upgrade, dan gunakan Slow-Motion.', W/2, H/2-18);
  ctx.fillText('Klik penjaga di bawah, lalu klik tanah untuk menanam.', W/2, H/2+8);
  ctx.fillText('Klik penjaga yang sudah ada untuk upgrade.', W/2, H/2+34);
  const pulse = 0.5+0.5*Math.sin(Date.now()/400);
  ctx.fillStyle = 'rgba(78,158,69,'+(0.7+0.3*pulse)+')';
  roundRect(W/2-140, H/2+70, 280, 62, 18); ctx.fill();
  ctx.fillStyle='#fff'; ctx.font='bold 24px Segoe UI';
  ctx.fillText('▶ MULAI', W/2, H/2+110);
  ctx.fillStyle='rgba(43,74,60,0.5)'; ctx.font='13px Segoe UI';
  ctx.fillText('Built with AISYS HTML5 Engine', W/2, H/2+170);
  ctx.fillText('STIKOM YOS SUDARSO', W/2, H/2+190);
}
function drawOver(){
  drawBackground();
  ctx.fillStyle='rgba(255,255,255,0.85)'; roundRect(W/2-300, H/2-190, 600, 380, 28); ctx.fill();
  ctx.textAlign='center';
  ctx.fillStyle='#D95757'; ctx.font='bold 46px Segoe UI';
  ctx.fillText('Kebun Tumbang!', W/2, H/2-100);
  ctx.fillStyle='#2b4a3c'; ctx.font='22px Segoe UI';
  ctx.fillText('Skor Akhir: '+G.score, W/2, H/2-40);
  ctx.fillText('Gelombang Tercapai: '+G.wave, W/2, H/2-4);
  ctx.fillText('Hama Dikalahkan: '+G.totalKills, W/2, H/2+32);
  const pulse = 0.5+0.5*Math.sin(Date.now()/400);
  ctx.fillStyle = 'rgba(78,158,69,'+(0.7+0.3*pulse)+')';
  roundRect(W/2-130, H/2+70, 260, 58, 18); ctx.fill();
  ctx.fillStyle='#fff'; ctx.font='bold 22px Segoe UI';
  ctx.fillText('🔄 MAIN LAGI', W/2, H/2+108);
  ctx.fillStyle='rgba(43,74,60,0.5)'; ctx.font='13px Segoe UI';
  ctx.fillText('Built with AISYS HTML5 Engine', W/2, H/2+160);
  ctx.fillText('STIKOM YOS SUDARSO', W/2, H/2+180);
}

/* ============ RENDER ============ */
function render(){
  ctx.save();
  if(G.shake>0){ ctx.translate((Math.random()-.5)*G.shake, (Math.random()-.5)*G.shake); }
  if(G.state==='menu'){ drawMenu(); ctx.restore(); return; }
  if(G.state==='over'){ drawOver(); ctx.restore(); return; }
  drawBackground();
  drawPath();
  drawGoal();
  drawPlacementHint();
  for(const t of G.towers) drawTower(t);
  for(const e of G.enemies) drawEnemy(e);
  for(const b of G.bullets) drawBullet(b);
  drawParticles();
  if(G.slowTimer>0){
    ctx.fillStyle='rgba(120,200,255,0.10)'; ctx.fillRect(0,0,W,H);
  }
  drawHUD();
  ctx.restore();
}

/* ============ INPUT ============ */
function canvasPos(ev){
  const r = cv.getBoundingClientRect();
  const cx = (ev.clientX - r.left) * (W/r.width);
  const cy = (ev.clientY - r.top) * (H/r.height);
  return {x:cx, y:cy};
}
cv.addEventListener('pointermove', ev=>{
  const p = canvasPos(ev);
  G.hoverCell = {x:Math.round(p.x/10)*10, y:Math.round(p.y/10)*10};
});
cv.addEventListener('pointerdown', ev=>{
  unlockAudio();
  const p = canvasPos(ev);
  if(G.state==='menu'){
    if(Math.abs(p.x-W/2)<150 && Math.abs(p.y-(H/2+100))<40){ newGame(); G.state='play'; startWave(); }
    return;
  }
  if(G.state==='over'){
    if(Math.abs(p.x-W/2)<140 && Math.abs(p.y-(H/2+99))<40){ newGame(); G.state='play'; startWave(); }
    return;
  }
  // tower buttons
  const types = ['semprot','jaring','api'];
  for(let i=0;i<3;i++){
    const bx=16+i*150, by=H-96;
    if(p.x>=bx&&p.x<=bx+138&&p.y>=by&&p.y<=by+80){ G.selected = G.selected===types[i]?null:types[i]; return; }
  }
  // slow motion
  if(p.x>=W-190&&p.x<=W-16&&p.y>=H-96&&p.y<=H-16){
    if(G.slowCd<=0){ G.slowTimer=4; G.slowCd=20; SFX.slow(); }
    return;
  }
  // existing tower click -> upgrade
  for(const t of G.towers){
    if(Math.hypot(t.x-p.x, t.y-p.y) < 30){ upgradeTower(t); return; }
  }
  // place
  if(G.selected){ placeTower(G.selected, Math.round(p.x/10)*10, Math.round(p.y/10)*10); }
});
window.addEventListener('keydown', ev=>{
  unlockAudio();
  if(G.state==='menu' && (ev.key===' '||ev.key==='Enter')){ newGame(); G.state='play'; startWave(); return; }
  if(G.state==='over' && (ev.key===' '||ev.key==='Enter')){ newGame(); G.state='play'; startWave(); return; }
  if(G.state!=='play') return;
  if(ev.key==='1') G.selected = G.selected==='semprot'?null:'semprot';
  if(ev.key==='2') G.selected = G.selected==='jaring'?null:'jaring';
  if(ev.key==='3') G.selected = G.selected==='api'?null:'api';
  if(ev.key===' '){ ev.preventDefault(); if(G.slowCd<=0){ G.slowTimer=4; G.slowCd=20; SFX.slow(); } }
  if(ev.key==='u'||ev.key==='U'){
    let best=null,bd=1e9;
    for(const t of G.towers){ const d=Math.hypot(t.x-(G.hoverCell?G.hoverCell.x:0), t.y-(G.hoverCell?G.hoverCell.y:0)); if(d<bd){bd=d;best=t;} }
    if(best && bd<40) upgradeTower(best);
  }
});

/* ============ LOOP ============ */
let last = performance.now();
function loop(now){
  const dt = Math.min(0.05, (now-last)/1000); last = now;
  update(dt); render();
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);
</script>
